def dump(seg):
    for r in seg:
        assert set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, r["case_id"]
        assert set(r["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}, r["case_id"]
        assert 0.0 <= r["confidence"] <= 1.0
        p = os.path.join(OUT, r["case_id"] + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(r, f, ensure_ascii=False, indent=1)
        with open(p, encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == r["case_id"]
    print("segment ok:", len(seg))

